import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import { Button, Select, type LinImageUploadItem } from '@linm-soft-org/linm-web-common-components';
import { scykRoutes } from '../../config/scykRoutes';
import { incidentPublicReportService } from '../../services/incidentPublicReports';
import { guestCommitFile } from '../../services/incidentPublicReports/guestFiles';
import {
  IncidentPublicReporterKind,
  createEmptyPublicReport,
  type IncidentPublicReport,
  type IncidentPublicReportGuestInit,
} from '../../models/IncidentPublicReport';
import { getOrCreatePublicDeviceId } from '../../utils/publicDeviceId';
import { utcToLocalInputValue, localInputToISOWithOffset } from '../../utils/dateTime';
import { getApiErrorMessage } from '../../utils/apiMessages';
import { useAppNavigate } from '../../hooks/useAppNavigate';
import { useGuestPublicFileSession } from '../../hooks/useGuestPublicFileSession';
import {
  SCYK_PUBLIC_REPORT_ENTITY_TYPE,
  scykPublicReportImageUploadLabels,
} from '../../config/scykPublicReportImageUpload';
import {
  PublicReportPhotosSection,
  resolveUploadDisplayName,
  toPublicReportAttachmentDtos,
  type PublicReportUploadItem,
} from './PublicReportPhotosSection';
import { GuestPublicReportHeader } from './GuestPublicReportHeader';
import { GuestPublicReportSkeleton } from './GuestPublicReportSkeleton';
import styles from './IncidentPublicReportGuestPage.module.css';

const IncidentPublicReportGuestPage: React.FC = () => {
  const { companyCode = '' } = useParams<{ companyCode: string }>();
  const appNavigate = useAppNavigate();
  const [init, setInit] = useState<IncidentPublicReportGuestInit | null>(null);
  const [form, setForm] = useState<Partial<IncidentPublicReport>>(createEmptyPublicReport);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [submitError, setSubmitError] = useState<string | null>(null);
  const [saved, setSaved] = useState<IncidentPublicReport | null>(null);
  const [photos, setPhotos] = useState<LinImageUploadItem[]>([]);

  const L = (key: string) => init?.labels.find((o) => o.value === key)?.label ?? key;
  useGuestPublicFileSession(companyCode);

  useEffect(() => {
    getOrCreatePublicDeviceId();
  }, []);

  useEffect(() => {
    let cancelled = false;
    const t = setTimeout(() => {
      incidentPublicReportService.guestInit(companyCode)
        .then((data) => {
          if (cancelled) return;
          setInit(data);
          setForm(createEmptyPublicReport());
          setErrors({});
        })
        .catch((err) => { if (!cancelled) setSubmitError(getApiErrorMessage(err)); })
        .finally(() => { if (!cancelled) setLoading(false); });
    }, 0);
    return () => { cancelled = true; clearTimeout(t); };
  }, [companyCode]);

  const patch = (next: Partial<IncidentPublicReport>) => setForm((prev) => ({ ...prev, ...next }));

  const validate = (): Record<string, string> => {
    const next: Record<string, string> = {};
    if (form.reporterKind === IncidentPublicReporterKind.Family && !form.reporterName?.trim()) {
      next.reporterName = L('reporterName');
    }
    if (!form.reporterPhone?.trim()) next.reporterPhone = L('reporterPhone');
    if (!form.patientName?.trim()) next.patientName = L('patientName');
    if (!form.patientGender) next.patientGender = L('patientGender');
    if (!form.departmentId) next.departmentId = L('department');
    if (!form.occurredAt) next.occurredAt = L('occurredAt');
    if (!form.description?.trim()) next.description = L('description');
    if (photos.some((item) => item.status === 'uploading')) next.photos = L('uploadPending');
    else if (photos.some((item) => item.status === 'error')) next.photos = scykPublicReportImageUploadLabels.failed;
    return next;
  };

  const commitPhotos = async (): Promise<PublicReportUploadItem[]> => {
    const committed: PublicReportUploadItem[] = [];
    for (const item of photos as PublicReportUploadItem[]) {
      const displayName = resolveUploadDisplayName(item);
      if (item.status === 'committed' && item.attachmentId) {
        committed.push({ ...item, displayName });
        continue;
      }
      if (item.status !== 'staged' || !item.uploadId) continue;
      const savedFile = await guestCommitFile(companyCode, {
        uploadId: item.uploadId,
        entityType: SCYK_PUBLIC_REPORT_ENTITY_TYPE,
      });
      committed.push({
        ...item,
        attachmentId: savedFile.attachmentId,
        objectKey: savedFile.objectKey,
        contentType: savedFile.contentType,
        sizeBytes: savedFile.sizeBytes,
        status: 'committed',
        displayName: displayName || savedFile.fileName,
      });
    }
    return committed;
  };

  const handleSubmit = async () => {
    const next = validate();
    setErrors(next);
    if (Object.keys(next).length > 0) return;
    setSaving(true);
    setSubmitError(null);
    try {
      const dept = init?.departments.find((d) => d.id === form.departmentId);
      const committedPhotos = await commitPhotos();
      const result = await incidentPublicReportService.submit(companyCode, {
        companyCode,
        reporterKind: form.reporterKind,
        reporterName: form.reporterName ?? '',
        reporterPhone: form.reporterPhone ?? '',
        patientName: form.patientName ?? '',
        patientGender: form.patientGender ?? '',
        departmentId: form.departmentId,
        departmentName: dept?.name ?? form.departmentName ?? '',
        areaText: form.areaText ?? '',
        occurredAt: form.occurredAt,
        description: form.description ?? '',
        attachments: toPublicReportAttachmentDtos(committedPhotos),
      });
      setSaved(result);
      setPhotos(committedPhotos);
    } catch (err) {
      setSubmitError(getApiErrorMessage(err));
    } finally {
      setSaving(false);
    }
  };

  if (loading || !init) {
    if (!loading && submitError) {
      return (
        <div className={styles.page} data-testid="incident-public-report-guest">
          <div className={styles.formBody}>
            <div className={styles.errorBanner}>{submitError}</div>
          </div>
        </div>
      );
    }
    return <GuestPublicReportSkeleton />;
  }

  if (saved) {
    return (
      <div className={styles.page} data-testid="incident-public-report-guest-success">
        <GuestPublicReportHeader
          title={init?.companyName || L('pageTitle')}
          companyCode={companyCode}
          label={L}
          showCreate
        />
        <div className={styles.formBody}>
          <div className={styles.success}>
            <h2>{L('successTitle')}</h2>
            <p>{L('successHint')}</p>
            <p><strong>{L('idCode')}: {saved.idCode}</strong></p>
          </div>
          <div className={styles.actions}>
            <Button variant="primary" onClick={() => appNavigate(scykRoutes.publicReports.guestView(companyCode, saved.id))}>
              {L('viewThis')}
            </Button>
            <Button variant="secondary" onClick={() => appNavigate(scykRoutes.publicReports.guestHistory(companyCode))}>
              {L('historyLink')}
            </Button>
            <Button variant="secondary" onClick={() => { setSaved(null); setForm(createEmptyPublicReport()); setPhotos([]); }}>
              {L('newReport')}
            </Button>
          </div>
        </div>
      </div>
    );
  }

  const genderOptions = (init?.patientGenders ?? []).map((o) => ({ value: o.value, label: o.label }));
  const deptOptions = (init?.departments ?? []).map((d) => ({ value: d.id, label: d.name }));

  return (
    <div className={styles.page} data-testid="incident-public-report-guest">
      <GuestPublicReportHeader
        title={init?.companyName || L('guestTitle')}
        subtitle={L('guestTitle')}
        companyCode={companyCode}
        label={L}
        showHistory
      />
      <div className={styles.formBody}>
        {submitError && <div className={styles.errorBanner}>{submitError}</div>}
        {Object.keys(errors).length > 0 && (
          <div className={styles.errorBanner}>{L('requiredBanner')}</div>
        )}
        <div className={styles.section}>
          <div className={styles.field}>
            <label>{L('reporterKind')} *</label>
            <div className={styles.radios}>
              {(init?.reporterKinds ?? []).map((opt) => (
                <label key={opt.value}>
                  <input
                    type="radio"
                    name="reporterKind"
                    checked={form.reporterKind === opt.value}
                    onChange={() => patch({ reporterKind: opt.value })}
                  />
                  {' '}{opt.label}
                </label>
              ))}
            </div>
          </div>
          {form.reporterKind === IncidentPublicReporterKind.Family && (
            <div className={`${styles.field} ${errors.reporterName ? styles.fieldHasError : ''}`}>
              <label>{L('reporterName')} *</label>
              <input
                value={form.reporterName ?? ''}
                className={errors.reporterName ? styles.inputError : ''}
                onChange={(e) => patch({ reporterName: e.target.value })}
              />
            </div>
          )}
          <div className={styles.row}>
            <div className={`${styles.field} ${errors.reporterPhone ? styles.fieldHasError : ''}`}>
              <label>{L('reporterPhone')} *</label>
              <input
                type="tel"
                value={form.reporterPhone ?? ''}
                className={errors.reporterPhone ? styles.inputError : ''}
                onChange={(e) => patch({ reporterPhone: e.target.value })}
              />
            </div>
            <div className={`${styles.field} ${errors.patientName ? styles.fieldHasError : ''}`}>
              <label>{L('patientName')} *</label>
              <input
                value={form.patientName ?? ''}
                className={errors.patientName ? styles.inputError : ''}
                onChange={(e) => patch({ patientName: e.target.value })}
              />
            </div>
          </div>
          <div className={styles.row}>
            <div className={`${styles.field} ${errors.patientGender ? styles.fieldHasError : ''}`}>
              <label>{L('patientGender')} *</label>
              <Select
                label=""
                options={genderOptions}
                value={form.patientGender ?? ''}
                placeholder={L('selectGender')}
                onChange={(e) => patch({ patientGender: e.target.value })}
                size="small"
              />
            </div>
            <div className={`${styles.field} ${errors.departmentId ? styles.fieldHasError : ''}`}>
              <label>{L('department')} *</label>
              <Select
                label=""
                options={deptOptions}
                value={form.departmentId ?? ''}
                placeholder={L('selectDepartment')}
                onChange={(e) => patch({
                  departmentId: e.target.value,
                  departmentName: deptOptions.find((d) => d.value === e.target.value)?.label ?? '',
                })}
                size="small"
              />
            </div>
          </div>
          <div className={styles.row}>
            <div className={styles.field}>
              <label>{L('areaText')}</label>
              <input value={form.areaText ?? ''} onChange={(e) => patch({ areaText: e.target.value })} />
            </div>
            <div className={`${styles.field} ${errors.occurredAt ? styles.fieldHasError : ''}`}>
              <label>{L('occurredAt')} *</label>
              <input
                type="datetime-local"
                className={errors.occurredAt ? styles.inputError : ''}
                value={utcToLocalInputValue(form.occurredAt)}
                onChange={(e) => patch({ occurredAt: localInputToISOWithOffset(e.target.value) })}
              />
            </div>
          </div>
          <div className={`${styles.field} ${errors.description ? styles.fieldHasError : ''}`}>
            <label>{L('description')} *</label>
            <textarea
              rows={4}
              className={errors.description ? styles.inputError : ''}
              value={form.description ?? ''}
              onChange={(e) => patch({ description: e.target.value })}
            />
          </div>
          {errors.photos && <div className={styles.fieldError}>{errors.photos}</div>}
          <PublicReportPhotosSection
            guest
            companyCode={companyCode}
            items={photos}
            onChange={setPhotos}
            title={L('photos')}
          />
          <div className={styles.actions}>
            <Button variant="primary" onClick={handleSubmit} disabled={saving}>
              {saving ? L('submitting') : L('submit')}
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default IncidentPublicReportGuestPage;
